    "bookPage": 124,
    "details": "They shine vibrantly, a beautiful diamond in the night sky.\nFire, Green, Magic, Ranged, Void\nManeuver\nDistance:  Ranged 10\nx  Self or one ally\nEffect:  The target has a +3 bonus to speed, they can fly, and their\nabilities ignore concealment. Additionally, whenever the target\ngains their Heroic Resource, they gain 1 additional Heroic Resource.\nThis effect lasts until the start of your next turn.\nPersistent 1:  The effect lasts until the start of your next turn.\nDraw Steel"
