    "details": "You teleport the target into the air and let the ground and the elemental force\nof fire do the rest.\nEarth, Fire, Magic, Ranged, Void\nMain action\nDistance:  Ranged 10\nx  One creature or object\nPower Roll + Reason:\n≤11:    You teleport the target up to 4 squares.\n12–16:    You teleport the target up to 6 squares.\n17+:    You teleport the target up to 8 squares.\nEffect:  If the target is teleported to a space where they would fall,\nthey immediately do so, treating the fall as if their Agility score were\n0. The target takes fire damage from the fall, and each enemy within\n3 squares of where they land takes the same amount of fire damage.\nThe ground within 3 squares of where the target lands is difficult\nterrain."
