    "details": "You disrupt an enemy’s strike and create a feedback loop in their mind,\npreventing them from focusing on future attacks.\nPsionic\nFree triggered\nDistance:  Self; see below\nx  Self or one creature\nTrigger:  The target takes damage from another creature’s ability\nwhile in the area of your Null Field ability.\nEffect:  The target takes half the damage, and if the triggering crea-\nture has  i<v  , they are dazed (save ends). While the triggering\ncreature is dazed this way, they take psychic damage equal to your\nIntuition score whenever they use a main action.\nNull"
