    "details": "Everyone get away from me!\nArea, Psionic, Telekinesis\nMain action\nDistance:  1 burst\nx  Each enemy in the area\nPower Roll + Reason:\n≤11:    3 damage; vertical push 2\n12–16:    6 damage; vertical push 4\n17+:    9 damage; vertical push 6\nStrained:  The size of the burst increases by 1, and you are weakened\nuntil the end of your turn."
