    "details": "You overload their senses, turning all their subconscious thoughts into\nconscious ones.\nPsionic, Ranged, Strike, Telepathy\nMain action\nDistance:  Ranged 10\nx  One creature\nPower Roll + Reason:\n≤11:    6 +  R  psychic damage;  i<w  , slowed (save ends)\n12–16:    10 +  R  psychic damage;  i<v  , weakened (save ends)\n17+:    14 +  R  psychic damage;  i<s  , dazed (save ends)\nStrained:  You start crying, and you can’t use triggered actions or\nmake free strikes until the end of the target’s next turn."
