    "details": "Your foe gets a glimpse of how it will end for them.\nChronopathy, Psionic, Melee\nMain action\nDistance:  Melee 2\nx  One enemy\nEffect:  The target has damage weakness 5 until the end of your next\nturn. Whenever the target takes damage while they have this weak-\nness, they are knocked prone.\nStrained:  This ability gains the Strike keyword as the vision hurts\nthe target’s psyche. You make a power roll, then are weakened\n(save ends).\nPower Roll + Presence:\n≤11:    8 +  P  psychic damage\n12–16:    13 +  P  psychic damage\n17+:    17 +  P  psychic damage"
