    "cost": 9,
    "resource": "Clarity",
    "bookPage": 196,
    "details": "Keep everything as it was. Ignore everything that will be.\nArea, Chronopathy, Psionic, Ranged\nMain action\nDistance:  4 cube within 10\nx  Each creature and object in the area\nEffect:  The area is frozen in time until the start of your next turn.\nEach object in the area is restrained and can’t fall until the effect\nends. Until the effect ends, creatures in the area who are reduced to\n0 Stamina or would die stay alive, and objects in the area that are\nreduced to 0 Stamina remain undestroyed.\nMake a power roll that targets each enemy in the area.\nPower Roll + Presence:\n≤11:     p<w  , the target is slowed until the effect ends\n12–16:     p<v  , the target’s speed is 0 until the effect ends\n17+:     p<s  , the target is restrained until the effect ends\nStrained:  Any creature or object force moved in the area takes 2 cor-\nruption damage for each square of the area they enter. Creatures and\nobjects restrained in the area can be force moved. You are restrained\nuntil the effect ends."
