    "details": "You forcibly stuff more moments into a critical point in time, knowing full\nwell you might need to steal some of your own.\nChronopathy, Psionic, Ranged\nMain action\nDistance:  Ranged 5\nx  Three allies\nEffect:  Each target can use any main action available to them as a\nfree triggered action, but they lose their main action on their next\nturn.\nStrained:  Make a power roll that targets you and each enemy within\ndistance.\nPower Roll + Presence:\n≤11:    4 corruption damage; slowed (save ends)\n12–16:    6 corruption damage; slowed (save ends)\n17+:    10 corruption damage; slowed (save ends)"
