    "details": "They’re so hurt by your performance, you start to believe it yourself.\nMelee, Strike, Weapon\nMain action\nDistance:  Melee 1\nx  One creature\nPower Roll + Agility:\n≤11:    6 +  A  damage;  p<w  , weakened (save ends)\n12–16:    10 +  A  damage ;  p<v  , weakened (save ends)\n17+:    14 +  A  damage;  p<s  , weakened (save ends)\nEffect:  You can become bleeding (save ends) to deal an extra 5 cor-\nruption damage to the target."
