    "bookPage": 208,
    "details": "We offered them a percentage of the gross. So they’re working for free!\nMagic, Ranged\nMain action\nDistance:  Ranged 10\nx  Special\nEffect:  A guest star appears to help you during the encounter: either\na bystander within distance uplifted by your magic, or a mysterious\nnew hero who appears in an unoccupied space within distance. This\nguest star is controlled by you, has their own turn, and shares your\ncharacteristics. Their Stamina maximum is half yours. They have no\nabilities other than your melee and ranged free strikes. At the end of\nthe encounter, or when the guest star is reduced to 0 Stamina, they\nretreat or revert to a bystander. The same bystander can’t be uplifted\nthis way more than once during an encounter."
