    "details": "Your performance travels and doesn’t stop moving until your audience is\ncompletely rocked.\nMagic, Melee, Ranged, Strike, Weapon\nMain action\nDistance:  Melee 1 or ranged 10\nx  One creature or object\nPower Roll + Presence:\n≤11:    5 +  P  damage\n12–16:    8 +  P  damage; push 3\n17+:    11 +  P  damage; push 5\nEffect:  You can choose to have this ability deal sonic damage. Addi-\ntionally, you can use this ability against the same target for the next\n2 combat rounds without spending drama."
