    "details": "It’s love and blood or drama and blood. Either way, there’s always blood.\nMelee, Strike, Weapon\nMain action\nDistance:  Melee 1\nx  One creature or object\nPower Roll + Agility:\n≤11:    12 +  A  damage;  m<w  , bleeding (save ends)\n12–16:    18 +  A  damage;  m<v  , bleeding (save ends)\n17+:    24 +  A  damage; bleeding (EoT), or if  m<s  , bleeding\nDraw Steel\n(save ends)"
