    "resource": "Drama",
    "bookPage": 213,
    "details": "You shine a bright light on the players on the stage and compel them to finish\nthe performance.\nArea, Magic, Ranged\nManeuver\nDistance:  5 cube within 10\nx  Each enemy in the area\nPower Roll + Presence:\n≤11:    6  damage ;  p<w  , the target can’t willingly leave the area\n(EoT)\n12–16:    8  damage;  p<v  , the target can’t willingly leave the\narea (save ends)\n17+:    12 damage; the target can’t willingly leave the area (EoT); if\np<s  , they can’t willingly leave the area (save ends)\nEffect:  Each ally within distance can’t obtain lower than a tier 2 out-\ncome on the next test they make before the start of your next turn."
