    "details": "Your story tells a tale of the villain’s waning power and how the heroes rose\nto the occasion to stop them.\nMagic, Melee, Ranged\nManeuver\nDistance:  Melee 1 or ranged 10\nx  One creature\nPower Roll + Presence:\n≤11:    The target takes a bane on ability rolls (save ends).\n12–16:    The target has a double bane on ability rolls (save ends).\n17+:    The target has a double bane on power rolls (save ends).\nEffect:  Choose one ally within distance. While the target is affected\nby this ability, each time they use an ability, that ally can make a\nfree strike against them after the ability is resolved."
